async function risky(fail) {
  if (fail) throw new Error("boom");
  return "fine";
}

async function main() {
  try {
    console.log(await risky(false));
    console.log(await risky(true));
  } catch (e) {
    console.log("caught:", e.message);
  }
}
main();

