async function mapAsync(values, fn) {
  return await Promise.all(values.map(v => fn(v)));
}

async function settleCounts(promises) {
  const rs = await Promise.allSettled(promises);
  let fulfilled = 0;
  let rejected = 0;
  for (const r of rs) {
    if (r.status === "fulfilled") fulfilled++;
    else rejected++;
  }
  return { fulfilled, rejected };
}

async function retry(fn, attempts) {
  for (let i = 1; i <= attempts; i++) {
    try {
      return await fn(i);
    } catch (e) {
      // try again
    }
  }
  return "gave up";
}

